 roleid:=pg_temp.river_entity('role',r->>'role_code',r->>'role_name','e5d0ce65-26a8-5aa6-9a12-5909ebc92d7b'::uuid);

 SELECT id INTO scopeid FROM public.industry_domains WHERE industry_id=i AND domain_id=d;
