   RAISE EXCEPTION 'Existing role context differs from workbook or is inactive: %. Review before changing production.',r->>'role_name';
  END IF;
 ELSE

 INSERT INTO public.role_family_roles ("id", "role_family_domain_id", "role_id", "is_active", "description", "observable_behaviours", "role_work_context", "typical_work_activities", "role_output_evidence", "primary_riasec", "secondary_riasec", "tertiary_riasec", "riasec_reason", "degree_gate", "direct_degree_mapping", "riasec_code_string", "aptitude_profile", "big_five_profile", "work_values_profile", "aptitude_assessment", "big5_assessment", "work_values_assessment") VALUES ('9b232666-f736-53e1-b02e-f5e084ae4e44'::uuid, familyid, roleid, true, (jsonb_populate_record(NULL::public.role_family_roles,jsonb_strip_nulls(to_jsonb(jsonb_populate_record(NULL::public.role_family_roles,r)))))."description", (jsonb_populate_record(NULL::public.role_family_roles,jsonb_strip_nulls(to_jsonb(jsonb_populate_record(NULL::public.role_family_roles,r)))))."observable_behaviours", (jsonb_populate_record(NULL::public.role_family_roles,jsonb_strip_nulls(to_jsonb(jsonb_populate_record(NULL::public.role_family_roles,r)))))."role_work_context", (jsonb_populate_record(NULL::public.role_family_roles,jsonb_strip_nulls(to_jsonb(jsonb_populate_record(NULL::public.role_family_roles,r)))))."typical_work_activities", (jsonb_populate_record(NULL::public.role_family_roles,jsonb_strip_nulls(to_jsonb(jsonb_populate_record(NULL::public.role_family_roles,r)))))."role_output_evidence", (jsonb_populate_record(NULL::public.role_family_roles,jsonb_strip_nulls(to_jsonb(jsonb_populate_record(NULL::public.role_family_roles,r)))))."primary_riasec", (jsonb_populate_record(NULL::public.role_family_roles,jsonb_strip_nulls(to_jsonb(jsonb_populate_record(NULL::public.role_family_roles,r)))))."secondary_riasec", (jsonb_populate_record(NULL::public.role_family_roles,jsonb_strip_nulls(to_jsonb(jsonb_populate_record(NULL::public.role_family_roles,r)))))."tertiary_riasec", (jsonb_populate_record(NULL::public.role_family_roles,jsonb_strip_nulls(to_jsonb(jsonb_populate_record(NULL::public.role_family_roles,r)))))."riasec_rea